CREATE OR REPLACE FUNCTION public.blog_post_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r text; BEGIN
IF auth.role()='authenticated' THEN r:=public.blog_role(); IF r IS NULL THEN RAISE EXCEPTION 'CMS access required'; END IF; IF r='writer' AND (NEW.status NOT IN ('draft','in_review') OR (TG_OP='UPDATE' AND OLD.status NOT IN ('draft','in_review')) OR NEW.created_by IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'Writers may only edit their own drafts'; END IF; END IF;
IF NEW.status IN ('published','scheduled') AND (btrim(NEW.title)='' OR btrim(NEW.body)='' OR (NEW.featured_image IS NOT NULL AND btrim(coalesce(NEW.image_alt,''))='')) THEN RAISE EXCEPTION 'Title, content and image alt text are required for publishing'; END IF;
IF NEW.status='scheduled' AND (NEW.scheduled_at IS NULL OR (NEW.scheduled_at<=now() AND (TG_OP='INSERT' OR OLD.status<>'scheduled' OR NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at))) THEN RAISE EXCEPTION 'Choose a future publishing time'; END IF;
IF TG_OP='UPDATE' THEN INSERT INTO public.blog_revisions(post_id,snapshot,created_by) VALUES(OLD.id,to_jsonb(OLD),auth.uid()); IF OLD.slug<>NEW.slug AND OLD.published_at IS NOT NULL THEN INSERT INTO public.blog_redirects(old_slug,post_id) VALUES(OLD.slug,OLD.id) ON CONFLICT(old_slug) DO UPDATE SET post_id=EXCLUDED.post_id; END IF; NEW.version:=OLD.version+1; END IF;
IF NEW.status='published' AND NEW.published_at IS NULL THEN NEW.published_at:=now(); END IF; NEW.updated_at:=now(); INSERT INTO public.blog_audit(post_id,action,actor_id,details) VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN 'created' ELSE NEW.status::text END,auth.uid(),jsonb_build_object('slug',NEW.slug)); RETURN NEW; END $$;